def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    threat_bids = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if opp.get('budget', 0) > 0:
                    threat_bids.append(bid)

    if not alive:
        return max(0.0, min(budget, 18.0))

    capacity = supply / float(WATER_REQ)

    highest_prev = max(threat_bids) if threat_bids else (max(prev_bids) if prev_bids else 0.0)
    second_prev = 0.0
    if len(threat_bids) >= 2:
        sorted_bids = sorted(threat_bids, reverse=True)
        second_prev = sorted_bids[int(1)]
    elif len(prev_bids) >= 2:
        sorted_bids = sorted(prev_bids, reverse=True)
        second_prev = sorted_bids[int(1)]

    urgent = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1

    if capacity <= 1.05:
        if urgent:
            target = max(72.0, highest_prev + 2.5)
        elif pressured:
            target = max(63.0, highest_prev + 1.2)
        else:
            target = max(52.0, highest_prev - 6.0)
    else:
        if urgent:
            target = max(58.0, second_prev + 1.5)
        elif pressured:
            target = max(46.0, second_prev + 0.8)
        else:
            target = max(34.0, highest_prev * 0.72)

    if day >= 8 and hp >= 6 and budget < 220:
        target *= 0.9
    if day <= 2 and hp >= 6 and capacity > 1.2:
        target *= 0.92

    if budget < target:
        if urgent:
            target = budget
        else:
            target = min(budget, max(15.0, budget * 0.82))

    target = min(target, budget)
    if budget > 0:
        target = max(0.0, target)
    else:
        target = 0.0

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # React to yesterday's bids (immediate opponent pressure)
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many water units are likely needed/affordable.
    # If supply is high enough for multiple units, we can bid lower; if low, bid higher.
    # Target is to secure at least 1 unit (9 water requirement) when possible.
    # Supply is 15-25 so 1 unit is always feasible.
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY + 1e-9)
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Base bid influenced by my HP and supply.
    if my_hp <= 2.0 or my_no_water_days >= 2:
        base = DAILY_SALARY * (0.85 + 0.1 * (1.0 - supply_ratio))
    elif my_hp <= 4.0:
        base = DAILY_SALARY * (0.65 + 0.15 * (1.0 - supply_ratio))
    else:
        base = DAILY_SALARY * (0.55 + 0.12 * (1.0 - supply_ratio))

    # If Alex is still alive, use yesterday's max as a proxy for how much it takes to beat them.
    # Yesterday: Alex avg bid ~76.59 and survived; so we bias slightly above a fraction of that.
    # We avoid hard-calling the exact number since we don't see today's bids.
    alex_prev = None
    for oid, o in alive_opps:
        if str(oid).lower() == 'alex':
            prev = o.get('previous_trace', {}) or {}
            if prev.get('bid', None) is not None:
                try:
                    alex_prev = float(prev.get('bid'))
                except Exception:
                    alex_prev = None
            break

    # Decide aggression level.
    # If yesterday highest bid was high, competition is stiff; bid closer to it.
    if highest_prev_bid >= DAILY_SALARY * 0.75:
        # Competing with a strong bidder (likely Alex)
        if my_hp > 3.0:
            bid = max(base, DAILY_SALARY * 0.55 + 0.25 * highest_prev_bid)
        else:
            bid = max(base, DAILY_SALARY * 0.75 + 0.35 * highest_prev_bid)
    else:
        # Competition was lower; bid near base but still enough to avoid water starvation.
        bid = base

    # If Alex existed yesterday and bid was moderate-high, nudge to beat them when I'm safe.
    if alex_prev is not None and alex_prev > 0:
        # Aim to be somewhat above a fraction of Alex's prior bid.
        bid = max(bid, 0.85 * alex_prev + 5.0)

    # Budget safety cap.
    bid = min(bid, my_budget)

    # Never bid negative.
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    WATER_REQ = 13
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_active = len(alive_opponents) + 1

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        base_bid = 75.0
    else:
        base_bid = sum(yesterday_bids) / len(yesterday_bids)

    if my_status['hp'] < 4:
        bid = min(my_status['budget'], base_bid * 1.2)
    else:
        bid = min(my_status['budget'], base_bid * 1.05)

    if supply < WATER_REQ * 1.2:
        bid = min(my_status['budget'], bid * 1.3)

    return float(max(10.0, bid))
